import { useEffect, useState } from "react";
import clsx from "clsx";
import { Icon } from "../ui/icons.jsx";

export default function BackToTop() {
    const [visible, setVisible] = useState(false);
    useEffect(() => {
        const sentinel = document.getElementById("inhalt");
        if (!sentinel)
            return;
        const observer = new IntersectionObserver(([entry]) => setVisible(entry.boundingClientRect.top < -800), { threshold: [0, 0.1, 0.5] });
        observer.observe(sentinel);
        return () => observer.disconnect();
    }, []);
    return (
        <button type="button" aria-label="Nach oben" onClick={() => window.scrollTo({ top: 0 })} className={clsx("fixed right-6 bottom-6 z-(--z-popover) grid size-11 place-items-center rounded-full bg-brand-600 text-white shadow-popover transition-opacity", visible ? "opacity-100" : "pointer-events-none opacity-0")}>
            <Icon name="arrowUp" />
        </button>
    );
}
